
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_bkl1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_bkl1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.907737565821640e-02, -1.833127077865422e-02, -1.729038862320149e-02, -1.586033349089819e-02, -1.394273995709635e-02, -1.147207899509143e-02, -8.499227093226138e-03, -5.329323289643837e-03, -2.601456218044319e-03, -9.764799208834689e-04, -5.981831808437123e-04, -9.270993453889764e-03, -2.088237512139951e-02, -6.758451309732851e-03, -1.435370347865719e-03, -1.561731687147849e-04, -5.797228039230319e-06, -4.784868368027506e-08, -4.846914401185075e-11, -1.916724192085884e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


